\label{cor:positive-root-asymptotics}
For each positive odd integer \(n\), let \(\xi_n\) denote
the unique positive zero of \(\mathrm{Le}_n\), and let \(\varphi=\frac{1+\sqrt5}{2}\).
Then
\[
\xi_{n+2}<\xi_n
\]
for every positive odd integer \(n\). Moreover,
\begin{equation}
\label{eq:positive-root-asymptotic}
\lim_{\substack{n\to\infty\\ n\ \mathrm{odd}}}
(n+1)\xi_n
=
2\log\varphi.
\end{equation}
Consequently,
\[
\xi_n\sim\frac{2\log\varphi}{n+1}
\qquad
(n\to\infty,\ n\ \mathrm{odd}),
\]
and the lower bound in
\eqref{eq:classification-positive-bounds}
is asymptotically sharp.

\label{thm:fp-contraction}
For $k=1,\ldots,n$, let
\[
D_{n,k}
=
\left\{
\theta\in\mathbb{C}:
\left|\theta-\frac{k\pi}{n+1}\right|
\leq\frac{1}{n+1}
\right\}.
\]
Then $T_{n,k}$ is well defined on $D_{n,k}$ and maps this disk into itself. Moreover,
\begin{equation}
\label{eq:fp-lipschitz}
|T_{n,k}(\theta)-T_{n,k}(\eta)|
\leq
\kappa_n|\theta-\eta|,
\qquad \theta,\eta\in D_{n,k},
\end{equation}
where
\[
\kappa_n
=
\frac{\sqrt{61}}{8(n+1)}
<1.
\]

\label{thm:fp-convergence}
For every \(k=1,\ldots,n\), the map \(T_{n,k}\) has a unique
fixed point \(\theta_*^{(k)}\) in \(D_{n,k}\).
For every initial value \(\theta_0^{(k)}\in D_{n,k}\), the iteration
\begin{equation}
\label{eq:fp-iteration}
\theta_{r+1}^{(k)}
=
T_{n,k}\bigl(\theta_r^{(k)}\bigr),
\qquad r=0,1,2,\ldots,
\end{equation}
converges geometrically to \(\theta_*^{(k)}\) and satisfies
\begin{equation}
\label{eq:fp-error}
\left|
\theta_r^{(k)}-\theta_*^{(k)}
\right|
\leq
\frac{\kappa_n^r}{1-\kappa_n}
\left|
\theta_1^{(k)}-\theta_0^{(k)}
\right|,
\qquad r\geq0.
\end{equation}
In particular, the initial values
\[
\theta_0^{(k)}=\frac{k\pi}{n+1},
\qquad k=1,\ldots,n,
\]
are admissible for every \(n\geq1\).

\label{thm:fp-strip}
For every $n\geq1$, all zeros $z$ of $\mathrm{Le}_n$ satisfy
\begin{equation}
\label{eq:fp-strip}
|\operatorname{Re}z|
\leq
2\sinh\!\left(\frac{1}{n+1}\right).
\end{equation}
Consequently,
\[
\lim_{n\to\infty}
\max_{\mathrm{Le}_n(z)=0}
|\operatorname{Re}z|
=
0.
\]

\label{cor:fp-aposteriori}
Let \(n\geq1\), \(k\in\{1,\ldots,n\}\), and let
\(\theta_r^{(k)}\) be the iteration defined by
\eqref{eq:fp-iteration}, with
\(\theta_0^{(k)}\in D_{n,k}\).
Let
\[
x_k=2i\cos\theta_*^{(k)}
\]
be the corresponding zero of \(\mathrm{Le}_n\).
For \(r\geq0\), set
\[
\widehat{\theta}_k=\theta_{r+1}^{(k)},
\qquad
\widehat{x}_k=2i\cos\widehat{\theta}_k.
\]
Then
\begin{equation}
\label{eq:fp-aposteriori-angle}
\left|
\widehat{\theta}_k-\theta_*^{(k)}
\right|
\leq
\frac{\kappa_n}{1-\kappa_n}
\left|
\theta_{r+1}^{(k)}-\theta_r^{(k)}
\right|,
\end{equation}
and
\begin{equation}
\label{eq:fp-aposteriori-root}
\left|\widehat{x}_k-x_k\right|
\leq
2\cosh\!\left(\frac{1}{n+1}\right)
\frac{\kappa_n}{1-\kappa_n}
\left|
\theta_{r+1}^{(k)}-\theta_r^{(k)}
\right|.
\end{equation}
Consequently, for any \(\varepsilon>0\), the stopping condition
\[
\left|
\theta_{r+1}^{(k)}-\theta_r^{(k)}
\right|<\varepsilon
\]
implies
\begin{equation}
\label{eq:fp-stopping-root-error}
\left|\widehat{x}_k-x_k\right|
<
2\cosh\!\left(\frac{1}{n+1}\right)
\frac{\kappa_n}{1-\kappa_n}\,\varepsilon.
\end{equation}
